/**
 * Compiles wasm/classify.c into src/classify-wasm-bytes.ts, the module as
 * base64 (the site needs no extra file). Needs clang with the wasm32 target
 * and wasm-ld (LLVM 17 or later). Run with `npm run build:wasm` after
 * changing wasm/.
 *
 * The generated file records a hash of the C source; a unit test fails when
 * the source changes without a rebuild.
 */
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
const source = 'wasm/classify.c';
const dir = mkdtempSync(join(tmpdir(), 'classify-wasm-'));
const out = join(dir, 'classify.wasm');
try {
  execFileSync(
    process.env.CLANG ?? 'clang',
    [
      '--target=wasm32',
      '-O3',
      '-msimd128',
      '-nostdlib',
      '-fno-builtin',
      '-Wall',
      '-Werror',
      '-Wl,--no-entry',
      '-Wl,--export=__heap_base',
      '-Wl,--strip-all',
      '-o',
      out,
      join(root, source),
    ],
    { stdio: 'inherit' },
  );
  const bytes = readFileSync(out);
  const hash = createHash('sha256').update(readFileSync(join(root, source))).digest('hex');
  writeFileSync(
    join(root, 'src/classify-wasm-bytes.ts'),
    `// Generated by scripts/build-wasm.mjs from ${source}. Do not edit.\n` +
      `/** Hash of the C source this was built from (checked by test/classify-wasm.test.ts). */\n` +
      `export const CLASSIFY_WASM_HASH = '${hash}';\n` +
      `/** The compiled module (${bytes.length} bytes), base64. */\n` +
      `export const CLASSIFY_WASM_BASE64 =\n  '${bytes.toString('base64')}';\n`,
  );
  console.log(`src/classify-wasm-bytes.ts: ${bytes.length} bytes of WebAssembly`);
} finally {
  rmSync(dir, { recursive: true, force: true });
}
